#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec/1e9;
}

#define N 61440000
unsigned char *pt, *ct;
unsigned char key[16];
unsigned char nonce[12];

void ctr_chunk(unsigned char *out, const unsigned char *in, size_t len, unsigned int ctr_start) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char iv[16];
    memcpy(iv, nonce, 12);
    iv[12] = (ctr_start >> 24) & 0xff;
    iv[13] = (ctr_start >> 16) & 0xff;
    iv[14] = (ctr_start >> 8) & 0xff;
    iv[15] = ctr_start & 0xff;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, key, iv);
    int outl;
    EVP_EncryptUpdate(ctx, out, &outl, in, len);
    EVP_EncryptFinal_ex(ctx, out+outl, &outl);
    EVP_CIPHER_CTX_free(ctx);
}

typedef struct { int id; int nthreads; } arg_t;
void* worker(void *a) {
    arg_t *arg = (arg_t*)a;
    size_t chunk = N / arg->nthreads;
    size_t start = arg->id * chunk;
    size_t len = (arg->id == arg->nthreads-1) ? (N - start) : chunk;
    unsigned int ctr_start = 2 + (unsigned int)(start / 16);
    ctr_chunk(ct + start, pt + start, len, ctr_start);
    return NULL;
}

int main() {
    pt = malloc(N); ct = malloc(N);
    for (size_t i=0;i<N;i++) pt[i] = i & 0xff;
    memset(key, 0, 16); memset(nonce, 0, 12);

    // single thread
    double t0 = now();
    ctr_chunk(ct, pt, N, 2);
    double t1 = now();
    printf("CTR single: %.3f ms, %.2f GB/s\n", (t1-t0)*1000, N/1e9/(t1-t0));

    for (int nt = 2; nt <= 12; nt++) {
        pthread_t th[12]; arg_t args[12];
        t0 = now();
        for (int i=0;i<nt;i++){ args[i].id=i; args[i].nthreads=nt; pthread_create(&th[i],NULL,worker,&args[i]); }
        for (int i=0;i<nt;i++) pthread_join(th[i],NULL);
        t1 = now();
        printf("CTR %d threads: %.3f ms, %.2f GB/s\n", nt, (t1-t0)*1000, N/1e9/(t1-t0));
    }
    free(pt); free(ct);
    return 0;
}
