#include <wmmintrin.h>
#include <emmintrin.h>
#include <immintrin.h>
#include <openssl/evp.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdio.h>

// GF(2^128) multiply with reduction poly x^128+x^7+x^2+x+1
static inline __m128i gf_mul(__m128i a, __m128i b) {
    __m128i t0, t1, t2, t3, r;
    t0 = _mm_clmulepi64_si128(a, b, 0x00);
    t1 = _mm_clmulepi64_si128(a, b, 0x10);
    t2 = _mm_clmulepi64_si128(a, b, 0x01);
    t3 = _mm_clmulepi64_si128(a, b, 0x11);
    t1 = _mm_xor_si128(t1, t2);
    t2 = _mm_slli_si128(t1, 8);
    t1 = _mm_srli_si128(t1, 8);
    t0 = _mm_xor_si128(t0, t2);
    t3 = _mm_xor_si128(t3, t1);
    // reduce (t3:t0)
    r = t0;
    t1 = _mm_srli_si128(t3, 8);
    t2 = _mm_slli_si128(t3, 8);
    r = _mm_xor_si128(r, t1);
    t0 = _mm_xor_si128(t0, t2);
    t1 = _mm_clmulepi64_si128(t0, _mm_set_epi64x(0, 0xe100000000000000ULL), 0x00);
    r = _mm_xor_si128(r, t1);
    return r;
}

// ---- global state for threads ----
static const uint8_t *g_key;
static int g_keylen;
static const uint8_t *g_nonce;
static const uint8_t *g_pt;
static uint8_t *g_ct;
static size_t g_ptlen;
static __m128i g_H;
static int g_nthreads;
static __m128i *g_chunk_ghash; // per-chunk local GHASH results

typedef struct {
    int id;
} targ_t;

// CTR encrypt a chunk using OpenSSL EVP
static void ctr_chunk(uint8_t *out, const uint8_t *in, size_t len, uint32_t ctr_start) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher;
    if (g_keylen == 16) cipher = EVP_aes_128_ctr();
    else if (g_keylen == 24) cipher = EVP_aes_192_ctr();
    else cipher = EVP_aes_256_ctr();
    unsigned char iv[16];
    memcpy(iv, g_nonce, 12);
    iv[12] = (ctr_start >> 24) & 0xff;
    iv[13] = (ctr_start >> 16) & 0xff;
    iv[14] = (ctr_start >> 8) & 0xff;
    iv[15] = ctr_start & 0xff;
    EVP_EncryptInit_ex(ctx, cipher, NULL, g_key, iv);
    int outl;
    EVP_EncryptUpdate(ctx, out, &outl, in, len);
    EVP_EncryptFinal_ex(ctx, out + outl, &outl);
    EVP_CIPHER_CTX_free(ctx);
}

// GHASH over a buffer (len multiple of 16), starting from Y=0, return result
static __m128i ghash_blocks(const uint8_t *data, size_t nblocks) {
    __m128i y = _mm_setzero_si128();
    for (size_t i = 0; i < nblocks; i++) {
        __m128i x = _mm_loadu_si128((const __m128i*)(data + i*16));
        y = gf_mul(_mm_xor_si128(y, x), g_H);
    }
    return y;
}

static void* worker(void *a) {
    targ_t *arg = (targ_t*)a;
    int id = arg->id;
    int nt = g_nthreads;
    size_t chunk = g_ptlen / nt;
    size_t start = id * chunk;
    size_t len = (id == nt - 1) ? (g_ptlen - start) : chunk;
    uint32_t ctr_start = 2 + (uint32_t)(start / 16);
    // CTR encrypt
    ctr_chunk(g_ct + start, g_pt + start, len, ctr_start);
    // GHASH over this chunk's ciphertext
    g_chunk_ghash[id] = ghash_blocks(g_ct + start, len / 16);
    return NULL;
}

// compute H^k via repeated squaring
static __m128i h_pow(uint64_t k) {
    __m128i result = _mm_setzero_si128();
    // result = 1 (identity) represented as... we need multiplicative identity.
    // We'll compute via: start with H, and multiply for each set bit.
    // Simpler: use binary exponentiation with identity = 1 (0x...01)
    __m128i base = g_H;
    __m128i acc = _mm_set_epi64x(0, 1); // identity element 1
    while (k > 0) {
        if (k & 1) acc = gf_mul(acc, base);
        base = gf_mul(base, base);
        k >>= 1;
    }
    return acc;
}

// Main entry: encrypt plaintext with AES-GCM, output ciphertext and tag.
// Returns 0 on success.
int gcm_encrypt(const uint8_t *key, int keylen, const uint8_t *nonce,
                const uint8_t *pt, size_t ptlen,
                const uint8_t *aad, size_t aadlen,
                uint8_t *ct, uint8_t *tag, int nthreads) {
    g_key = key; g_keylen = keylen; g_nonce = nonce;
    g_pt = pt; g_ct = ct; g_ptlen = ptlen; g_nthreads = nthreads;

    // Compute H = AES_K(0^128)
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher;
    if (keylen == 16) cipher = EVP_aes_128_ecb();
    else if (keylen == 24) cipher = EVP_aes_192_ecb();
    else cipher = EVP_aes_256_ecb();
    EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL);
    unsigned char zero[16] = {0};
    unsigned char Hbuf[16];
    int outl;
    EVP_EncryptUpdate(ctx, Hbuf, &outl, zero, 16);
    g_H = _mm_loadu_si128((const __m128i*)Hbuf);

    // Compute E_K(J0) where J0 = nonce || 0x00000001
    unsigned char j0[16];
    memcpy(j0, nonce, 12);
    j0[12] = 0; j0[13] = 0; j0[14] = 0; j0[15] = 1;
    unsigned char ej0[16];
    EVP_EncryptUpdate(ctx, ej0, &outl, j0, 16);
    EVP_CIPHER_CTX_free(ctx);

    // Parallel CTR + GHASH
    g_chunk_ghash = malloc(sizeof(__m128i) * nthreads);
    pthread_t th[64];
    targ_t args[64];
    for (int i = 0; i < nthreads; i++) {
        args[i].id = i;
        pthread_create(&th[i], NULL, worker, &args[i]);
    }
    for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);

    // Combine GHASH
    size_t ct_blocks = ptlen / 16;
    size_t aad_blocks = aadlen / 16;

    // Y_aad = GHASH(AAD)
    __m128i y_aad = _mm_setzero_si128();
    if (aad_blocks > 0) y_aad = ghash_blocks(aad, aad_blocks);

    // Combine chunk GHASH results
    __m128i y_ct = _mm_setzero_si128();
    size_t chunk_blocks = ct_blocks / nthreads;
    for (int j = 0; j < nthreads; j++) {
        size_t e_j; // end block index (1-based) of chunk j
        if (j == nthreads - 1) e_j = ct_blocks;
        else e_j = (j + 1) * chunk_blocks;
        // contribution = L_j * H^{ct_blocks - e_j + 1}
        __m128i pw = h_pow(ct_blocks - e_j + 1);
        y_ct = _mm_xor_si128(y_ct, gf_mul(g_chunk_ghash[j], pw));
    }

    // Y = y_aad * H^{ct_blocks+1} XOR y_ct XOR len_block * H
    __m128i y = gf_mul(y_aad, h_pow(ct_blocks + 1));
    y = _mm_xor_si128(y, y_ct);

    // length block: [aadlen*8 (64-bit BE) || ptlen*8 (64-bit BE)]
    unsigned char lenblock[16];
    uint64_t aad_bits = (uint64_t)aadlen * 8;
    uint64_t ct_bits = (uint64_t)ptlen * 8;
    for (int i = 0; i < 8; i++) lenblock[i] = (aad_bits >> (56 - 8*i)) & 0xff;
    for (int i = 0; i < 8; i++) lenblock[8+i] = (ct_bits >> (56 - 8*i)) & 0xff;
    __m128i lb = _mm_loadu_si128((const __m128i*)lenblock);
    y = _mm_xor_si128(y, gf_mul(lb, g_H));

    // tag = y XOR E(J0)
    __m128i tagv = _mm_xor_si128(y, _mm_loadu_si128((const __m128i*)ej0));
    _mm_storeu_si128((__m128i*)tag, tagv);

    free(g_chunk_ghash);
    return 0;
}
